const profileFields = {chineseName:'中文姓名',dateOfBirth:'出生日期',school:'學校',parentRelation:'關係',parentSurname:'家長姓氏',parentGivenName:'家長名字',parentLanguage:'慣用語言',parentEmail:'電郵',parentMobile:'手提電話',parentPhone:'電話',region:'地區',area:'區域',address:'地址',remark:'學生／家長備註',fpsRemark:'轉數快備註',referralCode:'推薦碼',referralNotes:'推薦備註',marketingNotes:'推廣備註',paymentReminder:'繳費提示',marketingOptIn:'推廣訊息設定'};
export function staffText(value) {
 if(typeof value !== 'string')return value;
 if(Object.hasOwn(words,value))return words[value];
 let match;
 if((match=/^(\d{4}-\d{2}-\d{2}): (.+)$/.exec(value)))return staffDate(match[1])+ '：'+staffText(match[2]);
 if((match=/^Choose a valid date in the (\d{4}) leave year\.$/.exec(value)))return '請選擇 '+match[1]+' 年內的有效休假日期。';
 if((match=/^Enter a valid date of birth on or before (\d{4}-\d{2}-\d{2})\.$/.exec(value)))return '請輸入不遲於 '+staffDate(match[1])+' 的有效出生日期。';
 if((match=/^This profile field cannot be edited: (.+)\.$/.exec(value)))return '無法編輯此欄位：'+(profileFields[match[1]]||'系統欄位')+'。';
 if((match=/^Choose yes or no for (.+)\.$/.exec(value)))return '請為「'+(profileFields[match[1]]||'此欄位')+'」選擇是或否。';
 if((match=/^Enter text for (.+)\.$/.exec(value)))return '請在「'+(profileFields[match[1]]||'此欄位')+'」輸入文字。';
 if((match=/^(.+) is too long\.$/.exec(value)))return '「'+(profileFields[match[1]]||'此欄位')+'」的內容過長。';
 if((match=/^This student has a separate lesson on (\d{4}-\d{2}-\d{2}) outside the receipt’s regular timetable\. Review that booking before changing the regular schedule\.$/.exec(value)))return '學生於 '+staffDate(match[1])+' 另有收據常規課表以外的課堂，請先覆核該課堂。';
 if((match=/^This student has another future paid period or regular lesson after (\d{4}-\d{2}-\d{2})\. Review that period together before applying a permanent change\.$/.exec(value)))return '學生於 '+staffDate(match[1])+' 之後另有已繳費期數或常規課堂，請一併覆核後再永久更改課表。';
 if(value==='This date range overlaps another future paid period. Review that period together before applying this change.')return '此日期範圍與另一個未來已繳費期數重疊，請一併覆核後再套用更改。';
 return familyText(value, 'parent');
}
export const staffDate = (value, options = {}) => familyDate(value, 'parent', options);
export const staffContent = value => staffText(familyContent(value, 'parent'));
// The editable profile fields retain user-authored values exactly. Translate only
// untouched fictional defaults; imported pupils do not acquire fictional facts.
export function staffProfile(state, profile) {
 const saved=state.studentProfiles?.[profile.studentId]||{};
 return {...profile,...Object.fromEntries(['school','parentRelation','parentLanguage'].filter(key=>!Object.hasOwn(saved,key)).map(key=>[key,staffContent(profile[key])]))};
}
